{"content":"def fizzbuzz(n):
    """Return FizzBuzz strings for 1 through n (empty when n <= 0)."""
    result = []
    for number in range(1, n + 1):
        if number % 15 == 0:
            result.append("FizzBuzz")
        elif number % 3 == 0:
            result.append("Fizz")
        elif number % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(number))
    return result
