{"content":"import unittest

from fizzbuzz import fizzbuzz


class FizzBuzzTests(unittest.TestCase):
    def test_first_fifteen_values(self):
        self.assertEqual(
            fizzbuzz(15),
            [
                "1", "2", "Fizz", "4", "Buzz",
                "Fizz", "7", "8", "Fizz", "Buzz",
                "11", "Fizz", "13", "14", "FizzBuzz",
            ],
        )

    def test_single_value(self):
        self.assertEqual(fizzbuzz(1), ["1"])

    def test_zero(self):
        self.assertEqual(fizzbuzz(0), [])

    def test_negative_value(self):
        self.assertEqual(fizzbuzz(-5), [])

    def test_rules_over_larger_range(self):
        result = fizzbuzz(100)
        self.assertEqual(len(result), 100)
        for number, value in enumerate(result, start=1):
            with self.subTest(number=number):
                self.assertIsInstance(value, str)
                expected = ("Fizz" if number % 3 == 0 else "") + (
                    "Buzz" if number % 5 == 0 else ""
                )
                self.assertEqual(value, expected or str(number))


if __name__ == "__main__":
    unittest.main()
